{
"rules": [
{
"id": "r1",
"text": "If the chart's printed percentage labels are treated as the authoritative 'labeled rating share' values, then the category whose label is numerically greatest is the one with the highest current labeled rating share, and the corresponding public option label is the required follow-up category.",
"component": "encoding/task relation",
"conditions": "Assumes the printed percentage inscriptions are the intended rating-share values and that the public option labels map one-to-one to the chart categories."
},
{
"id": "r2",
"text": "If the chart's vertical axis position (Value) is treated as the authoritative rating-share value instead of the printed labels, then the category whose point is highest on the page is the one with the highest current rating share, and the corresponding public option label is the required follow-up category.",
"component": "encoding/task relation",
"conditions": "Assumes the y-axis 'Value' scale is the intended rating-share measure and that the printed percentage labels are decorative or inconsistent with the axis."
},
{
"id": "r3",
"text": "If the public task requires selecting a category from the provided option_labels, then any chart category that does not appear in option_labels cannot be selected, and the highest-share category must be chosen from among the available options only.",
"component": "task-to-action relation",
"conditions": "Assumes the option_labels list is exhaustive for the primary field and that no other category can be entered."
}
],
"chains": [
{
"chain_id": "base_c1",
"rule_id": "r1",
"observations": [
{
"ref": "chart_1",
"location": "above the point aligned with the 'Design' x-axis tick",
"content": "the inscription '52%' is printed directly above the blue circular mark"
},
